<?php declare(strict_types=1);$e=static fn(mixed $v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$components=dirname(__DIR__,2).'/components';ob_start();$breadcrumbItems=[['label'=>'Dashboard','url'=>'/dashboard'],['label'=>'Community Actions','url'=>'/community-actions'],['label'=>$context->propertyDisplayName,'url'=>'/community-actions/'.$context->propertySlug],['label'=>'Application Reviews','current'=>true]];require $components.'/breadcrumb.php';$heading='Application Reviews';$description=$context->propertyDisplayName.' — Submit prospects for Corporate review and follow application decisions.';$eyebrow='Community Actions';$actionsHtml='<a class="btn gateway-button gateway-button--primary" href="/community-actions/'.$e($context->propertySlug).'/application-reviews/create">Submit Prospect</a>';require $components.'/page-header.php';if($success!==''):?><div class="alert gateway-alert gateway-alert--success" role="status"><?=$e($success)?></div><?php endif;?><form class="gateway-filter-bar" method="get" action="/community-actions/<?=$e($context->propertySlug)?>/application-reviews"><label>Search<input class="form-control" type="search" name="search" value="<?=$e($search)?>" placeholder="Prospect name"></label><label>Status<select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['pending_review'=>'Pending Review','approved'=>'Approved','denied'=>'Denied'] as $value=>$label):?><option value="<?=$value?>"<?=$status===$value?' selected':''?>><?=$label?></option><?php endforeach;?></select></label><button class="btn btn-secondary" type="submit">Apply Filters</button></form><?php if($reviews===[]):$emptyTitle='No application reviews';$emptyMessage='Submit a prospect when the Rent Manager documents are ready.';$emptyIconHtml='';$emptyActionHtml='';require $components.'/empty-state.php';else:?><div class="table-responsive"><table class="table gateway-directory-table"><thead><tr><th scope="col">Prospect</th><th scope="col">Submitted</th><th scope="col">Status</th><th scope="col">Last Updated</th><th scope="col">Action</th></tr></thead><tbody><?php foreach($reviews as $review):?><tr><td><?=$e($review['prospect_name'])?></td><td><?=$e((new DateTimeImmutable($review['submitted_at']))->format('F j, Y \a\t g:i A'))?></td><td><?php $statusLabel=['pending_review'=>'Pending Review','approved'=>'Approved','denied'=>'Denied'][$review['status']];$statusType=['pending_review'=>'neutral','approved'=>'success','denied'=>'danger'][$review['status']];require $components.'/status-badge.php';?></td><td><?=$e((new DateTimeImmutable($review['updated_at']))->format('F j, Y \a\t g:i A'))?></td><td><a href="/community-actions/<?=$e($context->propertySlug)?>/application-reviews/<?=$e($review['public_id'])?>">View</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;$contentHtml=(string)ob_get_clean();$pageTitle='Application Reviews — '.$context->propertyDisplayName.' — NPM Gateway';$navbarItems=\NpmGateway\Support\Navigation::forRoute('/community-actions',dirname(__DIR__,4));$navbarUserLabel=$user->displayName;$navbarUserContext='@'.$user->username;require dirname(__DIR__,2).'/layouts/app.php';
